"""Brute-force solvers for OneInThreeSat and SubsetSum used in tests."""
from typing import List, Dict


def solve_one_in_three_sat(instance: Dict) -> bool:
    m = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]
    # iterate over all assignments
    for mask in range(1 << m):
        ok = True
        for clause in clauses:
            # count true variables in clause
            cnt = 0
            for var in clause:
                # var is 1-indexed
                if mask & (1 << (var - 1)):
                    cnt += 1
            if cnt != 1:
                ok = False
                break
        if ok:
            return True
    return False


def solve_subset_sum(instance: Dict) -> bool:
    numbers: List[int] = instance["numbers"]
    target: int = instance["target"]
    n = len(numbers)
    # simple recursion/backtrack
    def dfs(i: int, current: int) -> bool:
        if current == target:
            return True
        if i == n or current > target:
            return False
        # try include
        if dfs(i + 1, current + numbers[i]):
            return True
        # try exclude
        if dfs(i + 1, current):
            return True
        return False
    # handle negative target early
    if target < 0:
        return False
    if target == 0:
        return True
    return dfs(0, 0)

EOF"}

